-- Ranking Fit (Part 3): each vendor's lead feed ordered by how well the requirement fits them (2026-11-01;
-- Mitra: "fix the ranking from the paused features", "fix on your own").
-- Design: documentation/ranking-fit-design-2026-11-01.md; plan: documentation/ranking-fit-plan-2026-11-01.md.
-- GENERATED by scripts/ranking/fit-build-migration.mjs from scripts/ranking/fit-migration.sql — edit those, not this.
--
-- score = 0.45 text similarity + 0.20 category + 0.15 category answers + 0.12 location + 0.08 scale.
-- The last three are 0.5 when either side hasn't said, so a vendor with none of the new data keeps today's order.
-- Every vendor still sees every lead it saw before: only the order and a "near" flag change.

-- ── A category's family ────────────────────────────────────────────────────────────────────────────────────
-- The top-level seller category (src/data/sellerCategories.ts id) a categories row sits under. The categories
-- table is seeded from sellerCategories.ts by name; older categories outside it have no family.
create function public.category_root_of(p_category uuid)
returns text
language sql
stable
set search_path = ''
as $function$
  with recursive up as (
    select c.id, c.parent_id, c.name, c.grp, 0 as depth from public.categories c where c.id = p_category
    union all
    select c.id, c.parent_id, c.name, c.grp, up.depth + 1
      from public.categories c join up on c.id = up.parent_id
     where up.depth < 10
  )
  select r.root
    from up join (values
      ('fashion-accessories', 'Fashion Accessories (Unisex)', 'pieces'),
      ('raw-materials', 'Raw Materials – Fabrics & Inputs', 'metres'),
      ('trims-accessories', 'Trims & Accessories', 'pieces'),
      ('labels-tags', 'Labels & Tags', 'pieces'),
      ('packaging', 'Packaging', 'pieces'),
      ('apparel-home', 'Apparel & Home Categories', 'pieces'),
      ('machinery-equipment', 'Machinery & Equipment', 'pieces'),
      ('chemicals-dyes', 'Chemicals & Dyes', 'kg'),
      ('printing-manufacturing', 'Printing & Manufacturing Services', null),
      ('service-providers', 'Service Providers (Manufacturing & Fashion Ops)', null),
      ('logistics-supply-chain', 'Logistics & Supply Chain', null),
      ('it-software-saas', 'IT, Software & SaaS', null),
      ('finance-compliance', 'Finance & Compliance Services', null),
      ('marketing-pr-photography', 'Marketing, PR & Photography', null),
      ('freelancers-job-workers', 'Freelancers & Job Workers', null),
      ('cosmetics-beauty', 'Cosmetics & Beauty', 'pieces'),
      ('others-custom', 'Others (Custom)', 'pieces')
    ) as r(root, name, unit) on r.name = up.name
   where up.parent_id is null and up.grp = 'Taxonomy'
   limit 1
$function$;
revoke all on function public.category_root_of(uuid) from public, anon, authenticated;
grant execute on function public.category_root_of(uuid) to service_role;

-- The unit a family's capacity is compared in (src/data/vendorTypes.ts defaultCapacityUnit); null for services.
create function admin.category_root_unit(p_root text)
returns text
language sql
immutable
set search_path = ''
as $function$
  select r.unit from (values
      ('fashion-accessories', 'Fashion Accessories (Unisex)', 'pieces'),
      ('raw-materials', 'Raw Materials – Fabrics & Inputs', 'metres'),
      ('trims-accessories', 'Trims & Accessories', 'pieces'),
      ('labels-tags', 'Labels & Tags', 'pieces'),
      ('packaging', 'Packaging', 'pieces'),
      ('apparel-home', 'Apparel & Home Categories', 'pieces'),
      ('machinery-equipment', 'Machinery & Equipment', 'pieces'),
      ('chemicals-dyes', 'Chemicals & Dyes', 'kg'),
      ('printing-manufacturing', 'Printing & Manufacturing Services', null),
      ('service-providers', 'Service Providers (Manufacturing & Fashion Ops)', null),
      ('logistics-supply-chain', 'Logistics & Supply Chain', null),
      ('it-software-saas', 'IT, Software & SaaS', null),
      ('finance-compliance', 'Finance & Compliance Services', null),
      ('marketing-pr-photography', 'Marketing, PR & Photography', null),
      ('freelancers-job-workers', 'Freelancers & Job Workers', null),
      ('cosmetics-beauty', 'Cosmetics & Beauty', 'pieces'),
      ('others-custom', 'Others (Custom)', 'pieces')
  ) as r(root, name, unit) where r.root = p_root
$function$;
revoke all on function admin.category_root_unit(text) from public, anon, authenticated;

-- An answer as a set of trimmed, lower-case strings: one value or a list (lib/formAttributes.ts clean()).
create function admin.fit_values(p jsonb)
returns text[]
language sql
immutable
set search_path = ''
as $function$
  select coalesce(array_agg(distinct lower(btrim(s.x))) filter (where btrim(s.x) <> ''), '{}')
    from (select p #>> '{}' as x where jsonb_typeof(p) in ('string', 'number')
          union all
          select e #>> '{}' from jsonb_array_elements(case when jsonb_typeof(p) = 'array' then p else '[]'::jsonb end) e
           where jsonb_typeof(e) in ('string', 'number')) s
$function$;
revoke all on function admin.fit_values(jsonb) from public, anon, authenticated;

-- ── Where a vendor was, over time ──────────────────────────────────────────────────────────────────────────
-- A buyer's state is private (buyer_profiles is readable by the buyer and support only). Location is scored
-- against the vendor's state and served states AS THEY WERE WHEN THE LEAD WAS POSTED, so changing them later
-- can't be cycled to probe a posted lead's buyer: each lead tells a vendor at most what "Near you" says.
create table admin.vendor_location_history (
  id             bigserial primary key,
  vendor_id      uuid not null references public.vendor_profiles(id) on delete cascade,
  state_code     text,
  served_states  text[] not null default '{}',
  valid_from     timestamptz not null default clock_timestamp()
);
create index vendor_location_history_vendor on admin.vendor_location_history (vendor_id, valid_from desc, id desc);
revoke all on table admin.vendor_location_history from public, anon, authenticated;
revoke all on sequence admin.vendor_location_history_id_seq from public, anon, authenticated;

create function admin.vendor_location_track()
returns trigger
language plpgsql
security definer
set search_path = ''
as $function$
begin
  if tg_op = 'INSERT' or new.state_code is distinct from old.state_code or new.served_states is distinct from old.served_states then
    insert into admin.vendor_location_history (vendor_id, state_code, served_states)
    values (new.id, new.state_code, coalesce(new.served_states, '{}'));
  end if;
  return null;
end
$function$;
revoke all on function admin.vendor_location_track() from public, anon, authenticated;
create trigger trg_vendor_profiles_location_history
  after insert or update of state_code, served_states on public.vendor_profiles
  for each row execute function admin.vendor_location_track();

-- Today's locations count for every lead already posted.
insert into admin.vendor_location_history (vendor_id, state_code, served_states, valid_from)
select vp.id, vp.state_code, coalesce(vp.served_states, '{}'), '-infinity' from public.vendor_profiles vp;

-- ── The three new parts of Fit ─────────────────────────────────────────────────────────────────────────────
create function admin.rfq_fit(p_vendor uuid, p_rfq uuid)
returns table(attr_part double precision, loc_part double precision, scale_part double precision)
language plpgsql
stable
security definer
set search_path = ''
as $function$
declare
  r          record;
  a          record;
  v_state    text;
  v_served   text[];
  v_caps     text[];
  v_buyer    text;
  v_root     text;
  v_unit     text;
  v_cap      numeric;
  v_cap_unit text;
  v_mine     text[];
  v_theirs   text[];
  v_num      double precision := 0;
  v_den      double precision := 0;
begin
  select rq.attributes, rq.overseas, rq.buyer_id, rq.category_id, rq.quantity, rq.created_at into r
    from public.rfqs rq where rq.id = p_rfq;
  if not found then
    return;
  end if;
  select vp.capabilities into v_caps from public.vendor_profiles vp where vp.id = p_vendor;
  -- Where the vendor was when the lead was posted (see admin.vendor_location_history).
  select h.state_code, h.served_states into v_state, v_served
    from admin.vendor_location_history h
   where h.vendor_id = p_vendor and h.valid_from <= r.created_at
   order by h.valid_from desc, h.id desc
   limit 1;
  v_served := coalesce(v_served, '{}');
  v_caps := coalesce(v_caps, '{}');

  -- Category answers: the buyer's answers to questions that mean a listing question, against that question's
  -- answers on the vendor's live listings. A question the vendor's listings don't answer is skipped.
  for a in
    select j.value, d.match_key, d.w
      from jsonb_each(coalesce(r.attributes, '{}'::jsonb)) j
      cross join lateral (select max(ad.match_key) as match_key, max(ad.match_weight)::double precision as w
                            from public.attribute_definitions ad
                           where ad.form = 'requirement' and ad.key = j.key
                             and ad.match_weight > 0 and ad.match_key is not null) d
     where d.w is not null
  loop
    v_theirs := admin.fit_values(a.value);
    continue when cardinality(v_theirs) = 0;
    select coalesce(array_agg(distinct s.x), '{}') into v_mine
      from public.products p
      cross join lateral (
        select unnest(admin.fit_values(p.attributes -> a.match_key)) as x
        union all select unnest(admin.fit_values(p.attributes -> 'colours')) where a.match_key = 'colors'
        union all select lower(btrim(p.fabric)) where a.match_key = 'fabric'
        union all select lower(btrim(p.gsm)) where a.match_key = 'gsm'
        union all select lower(btrim(unnest(p.pattern))) where a.match_key = 'pattern'
        union all select lower(btrim(unnest(p.sizes))) where a.match_key = 'sizes'
      ) s
     where p.vendor_id = p_vendor and p.status = 'live' and coalesce(s.x, '') <> '';
    continue when cardinality(v_mine) = 0;
    v_den := v_den + a.w;
    if v_mine && v_theirs then
      v_num := v_num + a.w;
    end if;
  end loop;
  attr_part := case when v_den > 0 then v_num / v_den else 0.5 end;

  -- Location: the buyer's profile state against the vendor's base state and the states it serves.
  if r.overseas then
    loc_part := case when 'export_ready' = any(v_caps) then 1 else 0.5 end;
  else
    select bp.state_code into v_buyer from public.buyer_profiles bp where bp.id = r.buyer_id;
    loc_part := case
      when v_buyer is null or (v_state is null and cardinality(v_served) = 0) then 0.5
      when v_buyer = v_state then 1
      when v_buyer = any(v_served) then 0.8
      when cardinality(v_served) > 0 then 0
      else 0.25
    end;
  end if;

  -- Scale: monthly capacity for the requirement's family against the quantity, in the family's usual unit.
  v_root := public.category_root_of(r.category_id);
  v_unit := admin.category_root_unit(v_root);
  select vc.monthly_capacity, vc.unit into v_cap, v_cap_unit
    from public.vendor_capacity vc where vc.vendor_id = p_vendor and vc.category_root = v_root;
  scale_part := case
    when v_unit is not null and v_cap is not null and v_cap_unit = v_unit and coalesce(r.quantity, 0) > 0
      then least(1, v_cap / r.quantity)::double precision
    else 0.5
  end;
  return next;
end
$function$;
revoke all on function admin.rfq_fit(uuid, uuid) from public, anon, authenticated;

-- ── The lead feed ──────────────────────────────────────────────────────────────────────────────────────────
-- The pool (who sees which lead) is exactly as before; only the score and the new `near` column change.
drop function public.match_vendor_rfqs(uuid, integer);
create function public.match_vendor_rfqs(p_vendor_id uuid, match_count integer default 200)
returns table(rfq_id uuid, similarity double precision, category_match boolean, score double precision, near boolean)
language plpgsql
stable
security definer
set search_path to 'public', 'extensions'
as $function$
declare
  v_tier text := admin.vendor_overseas_tier(p_vendor_id);
begin
  if auth.uid() is not null and p_vendor_id <> auth.uid() then
    raise exception 'forbidden' using errcode = '42501';
  end if;

  return query
  with v as materialized (
    select vp.catalog_embedding as emb,
           (select array_agg(distinct p.category_id)
              from public.products p
             where p.vendor_id = vp.id
               and p.status = 'live'
               and p.category_id is not null) as cat_ids
    from public.vendor_profiles vp
    where vp.id = p_vendor_id
  ),
  pool as (
    select r.id, r.embedding, r.category_id, r.overseas
    from public.rfqs r
    where r.status = 'active'
      and r.vendor_id is null
      -- Not past its deadline (2026-10-19).
      and (r.expires_at is null or r.expires_at > now())
      -- Not a buyer who blocked this seller, or whom the seller blocked (20261018160200).
      and not public.chat_blocked_between(r.buyer_id, p_vendor_id)
      -- Overseas requirements are Gold's and VIP's (P7), or a vendor's who already quoted.
      -- overseas_rfq_visible's rule, inline (it is tested on every row).
      and (not r.overseas
           or v_tier = 'vip'
           or (v_tier = 'gold' and (r.overseas_vip_until is null or now() >= r.overseas_vip_until))
           or exists (select 1 from public.quotes q where q.rfq_id = r.id and q.vendor_id = p_vendor_id))
  ),
  scored as (
    select
      pool.id as rfq_id,
      case when v.emb is not null and pool.embedding is not null
           then (1 - (pool.embedding <=> v.emb))::double precision
      end as similarity,
      coalesce(pool.category_id is not null
                 and (pool.category_id = any(v.cat_ids)
                      -- 2026-10-17: "Others (custom)" is every seller's category (one with a live listing).
                      or (public.rfq_category_is_open(pool.category_id) and v.cat_ids is not null)), false) as category_match,
      f.attr_part, f.loc_part, f.scale_part, pool.overseas
    from pool cross join v
    cross join lateral admin.rfq_fit(p_vendor_id, pool.id) f
  )
  select
    s.rfq_id,
    s.similarity,
    s.category_match,
    (0.45 * coalesce(s.similarity, 0)
       + 0.20 * s.category_match::int
       + 0.15 * s.attr_part
       + 0.12 * s.loc_part
       + 0.08 * s.scale_part)::double precision as score,
    -- "Near you": the buyer's profile state is the vendor's, or one it serves.
    (s.loc_part >= 0.8 and not s.overseas) as near
  from scored s
  order by score desc, s.similarity desc nulls last, s.rfq_id
  limit coalesce(match_count, 200);
end
$function$;
revoke all on function public.match_vendor_rfqs(uuid, integer) from public, anon;
grant execute on function public.match_vendor_rfqs(uuid, integer) to authenticated, service_role;

-- ── Self-checks ────────────────────────────────────────────────────────────────────────────────────────────
do $check$
begin
  if not has_function_privilege('authenticated', 'public.match_vendor_rfqs(uuid,integer)', 'execute')
     or has_function_privilege('anon', 'public.match_vendor_rfqs(uuid,integer)', 'execute') then
    raise exception 'self-check: match_vendor_rfqs is not callable by signed-in users only';
  end if;
  if has_function_privilege('authenticated', 'admin.rfq_fit(uuid,uuid)', 'execute')
     or has_function_privilege('anon', 'admin.rfq_fit(uuid,uuid)', 'execute')
     or has_function_privilege('authenticated', 'public.category_root_of(uuid)', 'execute') then
    raise exception 'self-check: clients can call the Fit helpers';
  end if;
  if (select count(*) from admin.vendor_location_history) < (select count(*) from public.vendor_profiles) then
    raise exception 'self-check: a vendor has no location history';
  end if;
  if has_table_privilege('authenticated', 'admin.vendor_location_history', 'select') then
    raise exception 'self-check: clients can read vendor location history';
  end if;
  -- Every top-level taxonomy row has a family (a renamed root would silently lose scale).
  if exists (select 1 from public.categories c
              where c.parent_id is null and c.grp = 'Taxonomy' and public.category_root_of(c.id) is null) then
    raise exception 'self-check: a top-level category has no seller family';
  end if;
end
$check$;
